    ,target_type
    ,IF(is_ads IS NOT NULL, CAST(is_ads AS STRING), 'false') AS is_ads
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,IF(TRIM(LOWER(search_entrance)) IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,CASE 
        WHEN CAST(location AS INT) <= 99 THEN location
        ELSE 'NA'
    END AS location
    ,IF(CAST(location AS INT) <= 3, '0~3', 'false') AS is_0to3_location
    ,IF(CAST(location AS INT) <= 9, '0~9', 'false') AS is_0to9_location
    ,IF(CAST(location AS INT) <= 19, '0~19', 'false') AS is_0to19_location
    ,IF(item_id IS NOT NULL, 'true', 'false') AS with_item
