-- Other search metrics that only has values when location_type = __ALL__ and with_item = __ALL__
CREATE TEMPORARY VIEW dwm_search_other_metrics_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,keyword
    ,CASE
        WHEN page_section IS NULL AND target_type = 'item' THEN 'item'
        WHEN page_section IS NULL AND target_type = 'video' THEN 'video'
        WHEN page_section IS NULL AND target_type = 'livestream' THEN 'livestream'
        ELSE 'Other'
    END AS card_type
    ,is_ads
    ,search_entrance
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,local_date
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(IF(page_type IN ( 'global_search', 'search_in_pdp', 'search_prefill') AND view_cnt > 0, view_cnt, NULL)) AS search_cnt
    ,SUM(IF(click_cnt > 0 AND target_type IN ('item','video','livestream')
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
        AND page_section IS NULL, 1, NULL)
    ) AS direct_search_success_cnt
    ,SUM(IF(click_cnt > 0 AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill') 
        AND ((target_type IN ('item','video','livestream', 'curated_search', 'live_stream_floating_preview') AND page_section IS NULL)
            OR ((target_type like 'shop%' or target_type like 'creator%') AND page_section IS NULL)
            OR (page_section = 'creator')
        ), 1, NULL)
    ) AS broad_search_success_cnt
    ,MAX(CASE WHEN view_cnt > 0 OR (imp_cnt > 0 AND target_type = 'no_recall_general') THEN true ELSE false END) AS keyword_flag
    ,MAX(CASE WHEN imp_cnt > 0 AND target_type = 'no_recall_general' THEN true ELSE false END) AS norecall_keyword_flag
FROM
    dwm_search_raw_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--
-- 995 metric --
CREATE TEMPORARY VIEW dws_995_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,card_type_exploded AS card_type
    ,is_ads_exploded AS is_ads
    ,search_entrance_exploded AS search_entrance
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv) / SUM(order_cnt) ELSE 0 END AS abs
FROM
    dwm_search_other_metrics_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(card_type, 'item+video+live')) AS card_type_exploded
LATERAL VIEW
    EXPLODE(ARRAY(is_ads, '__ALL__')) AS is_ads_exploded
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    local_date = ${local_date}
    AND card_type IN ('item', 'video', 'livestream')
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW global_search_abs995_benchmark_${grass_region_without_quote} AS
SELECT
    is_ads,
    approx_percentile(if(abs>0,abs, null), 0.995) as global_search_abs_995
FROM 
    dws_995_grouped_${grass_region_without_quote} a 
WHERE 
    search_entrance = '__ALL__'
    AND card_type = 'item+video+live'
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_995_metrics_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    card_type
    ,search_entrance
    ,a.is_ads
    ,SUM(IF(abs <= c.global_search_abs_995, gmv, 0)) AS gmv_995
    ,SUM(IF(abs <= c.global_search_abs_995, gmv, 0)) / COUNT(DISTINCT CASE WHEN imp_cnt > 0 AND abs <= c.global_search_abs_995 THEN a.user_id END) AS gmv_uu_995
    ,SUM(IF(abs <= c.global_search_abs_995, pc2_gmv, 0)) AS pc2_gmv_995
    ,SUM(IF(abs <= c.global_search_abs_995, pc2_gmv, 0)) / COUNT(DISTINCT CASE WHEN imp_cnt > 0 AND abs <= c.global_search_abs_995 THEN a.user_id END) AS pc2_gmv_uu_995
FROM
    dws_995_grouped_${grass_region_without_quote} a
LEFT JOIN
    global_search_abs995_benchmark_${grass_region_without_quote} c
ON
    a.is_ads = c.is_ads
GROUP BY
    1,2,3;

