-- no recall metric --
CREATE TEMPORARY VIEW dws_norecall_rate_${grass_region_without_quote} AS
SELECT
    search_entrance_exploded AS search_entrance
    ,IF(
        COUNT(DISTINCT CASE WHEN keyword_flag = true THEN (user_id, keyword) ELSE NULL END) != 0
        ,1.0 * COUNT(DISTINCT CASE WHEN keyword_flag = true AND norecall_keyword_flag = true THEN (user_id, keyword) ELSE NULL END)
            / COUNT(DISTINCT CASE WHEN keyword_flag = true THEN (user_id, keyword) ELSE NULL END)
        ,0
    ) AS norecall_rate
FROM
    dwm_search_other_metrics_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    local_date = ${local_date}
GROUP BY
    1;

--sql_divide_splitter--
-- search volume metric --
CREATE TEMPORARY VIEW dws_search_volume_${grass_region_without_quote} AS
SELECT
    search_entrance_exploded AS search_entrance
    ,COUNT(DISTINCT CASE WHEN search_cnt > 0 THEN (user_id, device_id, keyword) ELSE NULL END) AS search_volume
    ,COUNT(DISTINCT CASE WHEN direct_search_success_cnt > 0 THEN (user_id, device_id, keyword) ELSE NULL END) AS direct_search_success_volume
    ,COUNT(DISTINCT CASE WHEN broad_search_success_cnt > 0 THEN (user_id, device_id, keyword) ELSE NULL END) AS broad_search_success_volume
FROM
    dwm_search_other_metrics_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    local_date = ${local_date}
GROUP BY
    1;

