-- retention metric --
CREATE TEMPORARY VIEW user_retention_${grass_region_without_quote} AS 
SELECT
    user_id
    ,search_entrance_exploded AS search_entrance
    ,MAX(IF(local_date = date_sub(${local_date}, 7), true, false)) AS 7d_user
    ,MAX(IF(local_date = date_sub(${local_date}, 1), true, false)) AS 1d_user
    ,MAX(IF(local_date = ${local_date}, true, false)) AS 0d_user
FROM
    dwm_search_other_metrics_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    view_cnt > 0
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_retention_${grass_region_without_quote} AS
SELECT
    search_entrance
    ,SUM(IF(7d_user = true, 1, 0)) AS search_uu_7d
    ,SUM(IF(0d_user = true AND 7d_user = true, 1, 0)) AS retention_uu_7d
    ,SUM(IF(1d_user = true, 1, 0)) AS search_uu_1d
    ,SUM(IF(0d_user = true AND 1d_user = true, 1, 0)) AS retention_uu_1d
    ,SUM(IF(0d_user = true, 1, 0)) AS search_uu
FROM
    user_retention_${grass_region_without_quote}
GROUP BY 
    1;

