CREATE TEMPORARY VIEW dwm_ads_performance_${grass_region_without_quote} AS
SELECT
    IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,CASE 
        WHEN location <= 99 THEN CAST(location AS STRING)
        ELSE 'NA'
    END AS location
    ,IF(item_id IS NOT NULL, 'true', 'false') AS with_item
    ,SUM(expenditure_amt_usd) AS expenditure_amt_usd
    ,SUM(impression_cnt) AS paidads_imp_cnt
FROM
    mp_paidads.dwd_advertise_performance_di__reg_s0_live
WHERE
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND tz_type = 'local'
    AND entrance = 1
    AND user_id > 0
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_ads_performance_merge_${grass_region_without_quote} AS
SELECT
    COALESCE(a.search_entrance, b.search_entrance) AS search_entrance
    ,IF(COALESCE(a.search_entrance, b.search_entrance) IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,COALESCE(a.location, b.location) AS location
    ,IF(CAST(COALESCE(a.location, b.location) AS INT) BETWEEN 0 AND 3, '0~3', 'false') AS is_0to3_location
    ,IF(CAST(COALESCE(a.location, b.location) AS INT) BETWEEN 0 AND 9, '0~9', 'false') AS is_0to9_location
    ,IF(CAST(COALESCE(a.location, b.location) AS INT) BETWEEN 0 AND 19, '0~19', 'false') AS is_0to19_location
    ,COALESCE(a.with_item, b.with_item) AS with_item
    ,expenditure_amt_usd
    ,paidads_imp_cnt
    ,ads_load_denom_imp_cnt
FROM
    ads_load_denominator_${grass_region_without_quote} a
FULL JOIN
    dwm_ads_performance_${grass_region_without_quote} b
ON
    a.search_entrance = b.search_entrance
    AND a.location = b.location
    AND a.with_item = b.with_item;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_performance_${grass_region_without_quote} AS
SELECT
    search_entrance_exploded AS search_entrance
    ,location_exploded AS location
    ,with_item_exploded AS with_item
    ,SUM(expenditure_amt_usd) AS ads_revenue
    ,SUM(paidads_imp_cnt) AS paidads_imp_cnt
    ,SUM(ads_load_denom_imp_cnt) AS ads_load_denom_imp_cnt
FROM
    dwm_ads_performance_merge_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
LATERAL VIEW
    EXPLODE(FILTER(ARRAY(location, is_0to3_location, is_0to9_location, is_0to19_location, '__ALL__'), x -> x != 'false')) AS location_exploded
LATERAL VIEW
    EXPLODE(ARRAY(with_item, '__ALL__')) AS with_item_exploded
GROUP BY
    1,2,3;

--sql_divide_splitter--
-- srp duration metrics --
CREATE TEMPORARY VIEW dwd_srp_duration_${grass_region_without_quote} AS 
SELECT
    userid AS user_id
    ,IF(GET_JSON_OBJECT(data,'$.search_FE.search_entrance.entrance') IS NOT NULL AND TRIM(LOWER(GET_JSON_OBJECT(data,'$.search_FE.search_entrance.entrance'))) != '', TRIM(LOWER(GET_JSON_OBJECT(data,'$.search_FE.search_entrance.entrance'))), 'NA') AS search_entrance
    ,IF(GET_JSON_OBJECT(data,'$.search_FE.search_entrance.entrance') IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,SUM(CAST(GET_JSON_OBJECT(data,'$.duration') as bigint)) AS duration
FROM 
    traffic.shopee_traffic_dwd_click_hi__reg_s1_live 
WHERE  
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND page_type = 'search'
    AND operation= 'stay_view'
    AND GET_JSON_OBJECT(data,'$.search_FE.search_params.search_scenario.key') in ('PAGE_GLOBAL_SEARCH','PAGE_PDP_SEARCH','PAGE_PREFILL_SEARCH') --限制global search
    AND userid > 0 AND userid IS NOT NULL--限制登录用户
    AND CAST(GET_JSON_OBJECT(data,'$.duration') AS BIGINT) > 0  
    AND CAST(GET_JSON_OBJECT(data,'$.duration') AS BIGINT) < 36000000  -- 限制单次停留时长大于0s且小于10h（去除异常值）
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_srp_duration_${grass_region_without_quote} AS
SELECT
    search_entrance_exploded AS search_entrance
    ,SUM(duration) AS srp_duration
FROM
    dwd_srp_duration_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
GROUP BY
    1;

--sql_divide_splitter--
-- pdp duration metrics --
CREATE TEMPORARY VIEW dwd_pdp_${grass_region_without_quote} AS
SELECT 
    userid AS user_id
    ,session_id
    ,event_timestamp
    ,cast(GET_JSON_OBJECT(target_property, '$.duration') as double) as duration
    ,cast(GET_JSON_OBJECT(target_property_ext, '$.ctx_item_id') as STRING) as item_id
FROM
    traffic.shopee_traffic_dwd_click_hi__reg_s1_live
WHERE 
    local_date = ${local_date}
    AND operation = 'stay_view'
    AND page_type = 'product'
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_srp_click_${grass_region_without_quote} AS
select 
    userid AS user_id
    ,session_id
    ,event_timestamp
    ,GET_JSON_OBJECT(data,'$.search_FE.search_entrance.entrance') AS search_entrance
    ,cast(GET_JSON_OBJECT(data, '$.item.itemid') as STRING) as item_id
FROM traffic.shopee_traffic_dwd_click_hi__reg_s1_live
WHERE 
    local_date = ${local_date}
    AND operation = 'click'
    AND grass_region = ${grass_region}
    AND page_type = 'search'
    AND target_type = 'item'
    AND GET_JSON_OBJECT(data,'$.search_FE.search_params.search_scenario.key') 
        IN ('PAGE_GLOBAL_SEARCH','PAGE_PDP_SEARCH','PAGE_PREFILL_SEARCH');

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_pdp_duration_${grass_region_without_quote} AS
SELECT
    r.user_id
    ,IF(r.search_entrance IS NOT NULL AND TRIM(LOWER(r.search_entrance)) != '', TRIM(LOWER(r.search_entrance)), 'NA') AS search_entrance
    ,IF(TRIM(LOWER(r.search_entrance)) IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,SUM(duration) AS duration
FROM 
    dwd_srp_click_${grass_region_without_quote} r
LEFT JOIN
    dwd_pdp_${grass_region_without_quote} d
ON
    r.item_id = d.item_id
    AND r.session_id = d.session_id
    AND r.event_timestamp >= (d.event_timestamp-1000*60*10)
    AND r.event_timestamp <= d.event_timestamp
    AND r.user_id = d.user_id
GROUP BY
    1,2,3;

--sql_divide_splitter--

CACHE TABLE dws_pdp_duration_${grass_region_without_quote} AS
SELECT
    search_entrance_exploded AS search_entrance
    ,SUM(duration) AS pdp_duration
FROM
    dwd_pdp_duration_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
GROUP BY
    1;

