CREATE TEMPORARY VIEW dwd_video_order_${grass_region_without_quote} AS
SELECT
    user_id
    ,GET_JSON_OBJECT(click_data, '$.params.sv_source_page') as sv_source_page
    ,SUM(video_order_fraction) as order
    ,SUM(gmv_usd) as gmv_usd
FROM
    mp_content_oa.dwd_video_order_omni_local_content_direct_final_detail_di
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND user_id IS NOT NULL
    AND user_id > 0
    AND tz_type = 'local'
    AND GET_JSON_OBJECT(click_video_property, '$.business_id') in ('1003', '1019')
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_video_metrics_${grass_region_without_quote} AS
SELECT
    COALESCE(a.user_id, b.user_id) AS user_id

    ,SUM(watch_time_ms) AS staytime
    ,SUM(CASE WHEN a.sv_source_page IN
        ('iaa_srp_video_card','iaa_srp_video_creator_banner','iaa_sup_creator_hint_keyword'
        ,'iaa_sdp_creator_hint_keyword','iaa_creator_hint_keyword') THEN watch_time_ms ELSE NULL
    END) AS staytime_all_srp
    ,SUM(CASE WHEN a.sv_source_page IN ('iaa_srp_video_card') THEN watch_time_ms ELSE NULL END) AS staytime_video_srp

    ,SUM(vv) AS vv
    ,SUM(CASE WHEN a.sv_source_page IN
        ('iaa_srp_video_card','iaa_srp_video_creator_banner','iaa_sup_creator_hint_keyword'
        ,'iaa_sdp_creator_hint_keyword','iaa_creator_hint_keyword') THEN vv ELSE NULL
    END) AS vv_all_srp
    ,SUM(CASE WHEN a.sv_source_page IN ('iaa_srp_video_card') THEN vv ELSE NULL END) AS vv_video_srp

    ,SUM(order) AS order
    ,SUM(CASE WHEN b.sv_source_page IN
        ('iaa_srp_video_card','iaa_srp_video_creator_banner','iaa_sup_creator_hint_keyword'
        ,'iaa_sdp_creator_hint_keyword','iaa_creator_hint_keyword') THEN order ELSE NULL
    END) AS order_all_srp
    ,SUM(CASE WHEN b.sv_source_page IN ('iaa_srp_video_card') THEN order ELSE NULL END) AS order_video_srp

    ,SUM(gmv_usd) AS gmv_usd
    ,SUM(CASE WHEN b.sv_source_page IN
        ('iaa_srp_video_card','iaa_srp_video_creator_banner','iaa_sup_creator_hint_keyword'
        ,'iaa_sdp_creator_hint_keyword','iaa_creator_hint_keyword') THEN gmv_usd ELSE NULL
    END) AS gmv_usd_all_srp
    ,SUM(CASE WHEN b.sv_source_page IN ('iaa_srp_video_card') THEN gmv_usd ELSE NULL END) AS gmv_usd_video_srp
FROM
    dwd_video_ls_all_${grass_region_without_quote} a
FULL JOIN
    dwd_video_order_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.sv_source_page = b.sv_source_page
GROUP BY
    1;

--sql_divide_splitter--

CACHE TABLE dws_video_metrics_${grass_region_without_quote} AS
SELECT
    'item+video+live' AS card_type
    ,COALESCE(COUNT(DISTINCT CASE WHEN vv_all_srp > 0 THEN user_id ELSE NULL END), 0) AS search_to_video_viewer
    ,COALESCE(SUM(staytime_all_srp), 0) AS search_to_video_duration_time
    ,COALESCE(SUM(vv_all_srp), 0) AS search_to_video_vv
    ,COALESCE(SUM(order_all_srp), 0) AS search_to_video_order
    ,COALESCE(SUM(gmv_usd_all_srp), 0) AS search_to_video_gmv

    ,COALESCE(COUNT(DISTINCT CASE WHEN vv > 0 THEN user_id ELSE NULL END), 0) as all_video_side_viewer
    ,COALESCE(SUM(staytime), 0) as all_video_side_duration_time
    ,COALESCE(SUM(vv), 0) as all_video_side_vv
    ,COALESCE(SUM(order), 0) as all_video_side_order
    ,COALESCE(SUM(gmv_usd), 0) as all_video_side_gmv
FROM
    dwm_video_metrics_${grass_region_without_quote}
GROUP BY
    1
UNION ALL
SELECT
    'video' AS card_type
    ,COALESCE(COUNT(DISTINCT CASE WHEN vv_video_srp > 0 THEN user_id ELSE NULL END), 0) AS search_to_video_viewer
    ,COALESCE(SUM(staytime_video_srp), 0) AS search_to_video_duration_time
    ,COALESCE(SUM(vv_video_srp), 0) AS search_to_video_vv
    ,COALESCE(SUM(order_video_srp), 0) AS search_to_video_order
    ,COALESCE(SUM(gmv_usd_video_srp), 0) AS search_to_video_gmv

    ,COALESCE(COUNT(DISTINCT CASE WHEN vv > 0 THEN user_id ELSE NULL END), 0) as all_video_side_viewer
    ,COALESCE(SUM(staytime), 0) as all_video_side_duration_time
    ,COALESCE(SUM(vv), 0) as all_video_side_vv
    ,COALESCE(SUM(order), 0) as all_video_side_order
    ,COALESCE(SUM(gmv_usd), 0) as all_video_side_gmv
FROM
    dwm_video_metrics_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_video_duration_${grass_region_without_quote} AS
SELECT
    '__ALL__' AS search_entrance
    ,'item+video+live' AS card_type
    ,SUM(watch_time_ms) AS video_duration
FROM
