SELECT
    '__ALL__' AS search_entrance
    ,'video' AS card_type
    ,SUM(watch_time_ms) AS video_duration
FROM
    dwd_video_ads_ls_${grass_region_without_quote}
WHERE
    sv_source_page = 'iaa_srp_video_card'
GROUP BY
    1,2;

