-- live metrics --
CREATE TEMPORARY VIEW dwd_live_view_${grass_region_without_quote} AS
SELECT
    viewer_id as user_id
    ,view_event_id as event_id
    ,sum(duration_b * 1000) as duration_b
FROM 
    livestream.ls_mart_dwd_view_streaming_detail_di
WHERE
    tz_type = 'local'
    AND grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND viewer_id IS NOT NULL
    AND viewer_id > 0
GROUP BY
    1, 2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_live_duration_pv_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,IF(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance') IS NOT NULL AND TRIM(LOWER(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance'))) != '', TRIM(LOWER(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance'))), 'NA') AS search_entrance
    ,IF(TRIM(LOWER(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance'))) IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,CASE
        WHEN GET_JSON_OBJECT(data, '$.from_source') = 'global_search_srp_live_card_entry' THEN 1
        WHEN GET_JSON_OBJECT(data, '$.from_source') IN (
            'global_search_live_floating_entry'
            ,'pdp_search_live_floating_entry'
            ,'prefill_search_live_floating_entry'
            ,'other_search_live_floating_entry'
            ,'search_shop_entry'
            ,'search_kol_avatar_entry'
            ,'search_sup_creator_avatar_entry'
            ,'search_creator_page_avatar_entry'
        ) THEN 2
        ELSE 3
    END AS source_type
    ,SUM(duration_b) AS duration  -- duration_b单位为秒
    ,COUNT(1) AS view_pv
FROM 
    livestream.ls_mart_dwd_viewer_view_detail_di a 
LEFT JOIN
    dwd_live_view_${grass_region_without_quote} b 
ON
    a.user_id = b.user_id
    AND a.event_id = b.event_id
WHERE 
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND tz_type = 'local'
    AND a.user_id IS NOT NULL
    AND a.user_id > 0
GROUP BY 
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_live_order_${grass_region_without_quote} AS
SELECT
    order_buyer_id AS user_id
    ,COALESCE(GET_JSON_OBJECT(click_data,'$.live_scene_parameters.live_in_search.search_entrance'),'NA') AS search_entrance
    ,CASE WHEN GET_JSON_OBJECT(click_data, '$.ctx_from_source') = 'global_search_srp_live_card_entry' THEN 1
        WHEN GET_JSON_OBJECT(click_data, '$.ctx_from_source') IN (
            'global_search_live_floating_entry'
            ,'pdp_search_live_floating_entry'
            ,'prefill_search_live_floating_entry'
            ,'other_search_live_floating_entry'
            ,'search_shop_entry'
            ,'search_kol_avatar_entry'
            ,'search_sup_creator_avatar_entry'
            ,'search_creator_page_avatar_entry'
        ) THEN 2
        ELSE 3
    END AS source_type
    ,SUM(ls_order_fraction) as order
    ,SUM(gmv_usd) as gmv_usd
FROM
    mp_content_oa.dwd_ls_order_omni_local_content_final_detail_di
where
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND tz_type = 'local'
    AND order_cal_type = 'direct'
    AND is_content_directly_related = 1
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_live_order_flatten_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_entrance
    ,source_type
    ,order
    ,gmv_usd
FROM
    dwd_live_order_${grass_region_without_quote}
UNION ALL
SELECT
    user_id
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS search_entrance
    ,source_type
    ,order
    ,gmv_usd
FROM
    dwd_live_order_${grass_region_without_quote};

--sql_divide_splitter--

CACHE TABLE dws_live_order_${grass_region_without_quote} AS
SELECT
    '__ALL__' AS search_entrance
    ,'livestream' AS card_type
    ,COALESCE(SUM(CASE WHEN source_type IN (1) THEN order ELSE NULL END), 0) AS search_to_live_order
    ,COALESCE(SUM(CASE WHEN source_type IN (1) THEN gmv_usd ELSE NULL END), 0) AS search_to_live_gmv
    ,COALESCE(SUM(gmv_usd), 0) AS all_live_side_gmv
    ,COALESCE(SUM(order), 0) AS all_live_side_order
FROM
    dwd_live_order_${grass_region_without_quote} a
GROUP BY
    1,2
UNION ALL
SELECT
    search_entrance
    ,'livestream' AS card_type
    ,COALESCE(SUM(CASE WHEN source_type IN (1) THEN order ELSE NULL END), 0) AS search_to_live_order
    ,COALESCE(SUM(CASE WHEN source_type IN (1) THEN gmv_usd ELSE NULL END), 0) AS search_to_live_gmv
    ,COALESCE(SUM(gmv_usd), 0) AS all_live_side_gmv
    ,COALESCE(SUM(order), 0) AS all_live_side_order
FROM
    dwd_live_order_flatten_${grass_region_without_quote} a
GROUP BY
    1,2
UNION ALL
SELECT
    '__ALL__' AS search_entrance
    ,'item+video+live' AS card_type
    ,COALESCE(SUM(CASE WHEN source_type IN (1,2) THEN order ELSE NULL END), 0) AS search_to_live_order
    ,COALESCE(SUM(CASE WHEN source_type IN (1,2) THEN gmv_usd ELSE NULL END), 0) AS search_to_live_gmv
    ,COALESCE(SUM(gmv_usd), 0) AS all_live_side_gmv
    ,COALESCE(SUM(order), 0) AS all_live_side_order
FROM
    dwd_live_order_${grass_region_without_quote} a
GROUP BY
    1,2
UNION ALL
SELECT
    search_entrance
    ,'item+video+live' AS card_type
    ,COALESCE(SUM(CASE WHEN source_type IN (1,2) THEN order ELSE NULL END), 0) AS search_to_live_order
    ,COALESCE(SUM(CASE WHEN source_type IN (1,2) THEN gmv_usd ELSE NULL END), 0) AS search_to_live_gmv
    ,COALESCE(SUM(gmv_usd), 0) AS all_live_side_gmv
    ,COALESCE(SUM(order), 0) AS all_live_side_order
FROM
    dwd_live_order_flatten_${grass_region_without_quote} a
GROUP BY
    1,2;

--sql_divide_splitter--

CACHE TABLE dws_live_duration_${grass_region_without_quote} AS
SELECT
    search_entrance_exploded AS search_entrance
    ,'item+video+live' AS card_type
    ,COALESCE(COUNT(DISTINCT CASE WHEN source_type IN (1,2) THEN user_id ELSE NULL END), 0) AS search_to_live_viewer
    ,COALESCE(SUM(CASE WHEN source_type IN (1,2) THEN view_pv ELSE NULL END), 0) AS search_to_live_view_pv
    ,COALESCE(SUM(CASE WHEN source_type IN (1,2) THEN duration ELSE NULL END), 0) AS search_to_live_duration_time
    ,COALESCE(COUNT(DISTINCT user_id), 0) AS all_live_side_viewer
    ,COALESCE(SUM(view_pv), 0) AS all_live_side_view_pv
    ,COALESCE(SUM(duration), 0) AS all_live_side_duration_time
FROM
    dwd_live_duration_pv_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
GROUP BY
    1
UNION ALL
SELECT
    search_entrance_exploded AS search_entrance
    ,'livestream' AS card_type
    ,COALESCE(COUNT(DISTINCT CASE WHEN source_type IN (1) THEN user_id ELSE NULL END), 0) AS search_to_live_viewer
    ,COALESCE(SUM(CASE WHEN source_type IN (1) THEN view_pv ELSE NULL END), 0) AS search_to_live_view_pv
    ,COALESCE(SUM(CASE WHEN source_type IN (1) THEN duration ELSE NULL END), 0) AS search_to_live_duration_time
    ,COALESCE(COUNT(DISTINCT user_id), 0) AS all_live_side_viewer
    ,COALESCE(SUM(view_pv), 0) AS all_live_side_view_pv
    ,COALESCE(SUM(duration), 0) AS all_live_side_duration_time
FROM
    dwd_live_duration_pv_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
GROUP BY
    1;

--sql_divide_splitter--
-- search session level metrics --
CREATE TEMPORARY VIEW dwd_search_session_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,first_click_location
    ,max_imp_location
    ,search_time
FROM
    srdi_mart.dws_sr_data_warehouse_search_session_level_metircs_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0 AND user_id IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_first_location_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,first_click_location
    ,search_entrance
    ,is_content_entrance
    ,ROW_NUMBER() OVER(PARTITION BY user_id,search_session_id ORDER BY search_time ASC) as click_time_rank
    ,ROW_NUMBER() OVER(PARTITION BY user_id,search_session_id,search_entrance ORDER BY search_time ASC) as click_time_rank_tmp1
    ,ROW_NUMBER() OVER(PARTITION BY user_id,search_session_id,is_content_entrance ORDER BY search_time ASC) as click_time_rank_tmp2
FROM
    dwd_search_session_${grass_region_without_quote}
WHERE
    first_click_location IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_max_imp_location_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,search_entrance_exploded AS search_entrance
    ,MAX(max_imp_location) AS max_imp_location
FROM
    dwd_search_session_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    max_imp_location IS NOT NULL
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_first_location_${grass_region_without_quote} AS
SELECT
    '__ALL__' AS search_entrance
    ,AVG(first_click_location) as first_click_location_avg
    ,CASE
        WHEN COUNT(first_click_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(first_click_location)), 1 + CAST(COUNT(first_click_location) / 2 AS INT))
        ELSE NULL
    END AS first_click_location_p50
FROM
    dwd_first_location_${grass_region_without_quote}
WHERE
    click_time_rank = 1
GROUP BY
    1
UNION ALL
SELECT
    search_entrance
    ,AVG(first_click_location) as first_click_location_avg
    ,CASE
        WHEN COUNT(first_click_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(first_click_location)), 1 + CAST(COUNT(first_click_location) / 2 AS INT))
        ELSE NULL
    END AS first_click_location_p50
FROM
    dwd_first_location_${grass_region_without_quote}
WHERE
    click_time_rank_tmp1 = 1
GROUP BY
    1
UNION ALL
SELECT
    is_content_entrance AS search_entrance
    ,AVG(first_click_location) as first_click_location_avg
    ,CASE
        WHEN COUNT(first_click_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(first_click_location)), 1 + CAST(COUNT(first_click_location) / 2 AS INT))
        ELSE NULL
    END AS first_click_location_p50
FROM
    dwd_first_location_${grass_region_without_quote}
WHERE
    click_time_rank_tmp2 = 1
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_max_imp_location_${grass_region_without_quote} AS
SELECT
    search_entrance 
    ,AVG(max_imp_location) AS max_imp_location_avg
    ,CASE
        WHEN count(max_imp_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(max_imp_location)), 1 + CAST(COUNT(max_imp_location) / 2 AS INT))
        ELSE NULL
    END AS max_imp_location_p50
FROM
    dwd_max_imp_location_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_entrance_card_type_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
/*+ BROADCASTJOIN(b) */
/*+ BROADCASTJOIN(c) */
/*+ BROADCASTJOIN(d) */
/*+ BROADCASTJOIN(f) */
/*+ BROADCASTJOIN(g) */
/*+ BROADCASTJOIN(j) */
/*+ BROADCASTJOIN(k) */
/*+ BROADCASTJOIN(l) */
/*+ BROADCASTJOIN(m) */
/*+ BROADCASTJOIN(n) */
/*+ BROADCASTJOIN(o) */
/*+ BROADCASTJOIN(q) */
    a.card_type
    ,a.search_entrance
    ,a.is_ads
    ,imp_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,ppv_cnt
    ,ppv_uu
    ,cart_cnt
    ,cart_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,pc2_gmv
    ,ads_revenue
    ,search_uu
    ,search_volume
    ,direct_search_success_volume
    ,broad_search_success_volume
    ,search_uu_1d
    ,retention_uu_1d
    ,search_uu_7d
    ,retention_uu_7d
    ,cast(srp_duration AS DOUBLE) / cast(search_uu AS DOUBLE) AS srp_duration_per_uu
    ,cast(pdp_duration AS DOUBLE) / cast(search_uu AS DOUBLE) AS pdp_duration_per_uu
    ,cast(video_duration AS DOUBLE) / cast(search_uu AS DOUBLE) AS video_duration_per_uu
    ,cast(search_to_live_duration_time AS DOUBLE) / cast(search_uu AS DOUBLE) AS live_duration_per_uu

    ,max_imp_location_avg
    ,max_imp_location_p50
    ,first_click_location_avg
    ,first_click_location_p50

    ,search_scene_imp_cnt
    ,paidads_imp_cnt
    ,gmv_995
    ,gmv_uu_995
    ,pc2_gmv_995
    ,pc2_gmv_uu_995
    ,norecall_rate

    ,search_to_live_viewer
    ,search_to_live_view_pv
    ,search_to_live_duration_time
    ,search_to_live_order
    ,search_to_live_gmv
    ,all_live_side_viewer
    ,all_live_side_view_pv
    ,all_live_side_duration_time
    ,all_live_side_order
    ,all_live_side_gmv

    ,search_to_video_viewer
    ,search_to_video_vv
    ,search_to_video_duration_time
    ,search_to_video_order
    ,search_to_video_gmv
    ,all_video_side_viewer
    ,all_video_side_vv
    ,all_video_side_duration_time
    ,all_video_side_order
    ,all_video_side_gmv

    ,a.location
    ,a.with_item
    ,CAST(COALESCE(paidads_imp_cnt, 0) AS DOUBLE) / CAST(ads_load_denom_imp_cnt AS DOUBLE) AS ads_load

    ,all_ads_session_cnt
    ,search_session_cnt

    ,high_gmv_order_cnt_995_v2
    ,high_gmv_995_v2
    ,high_pc2_gmv_995_v2
    ,low_gmv_order_cnt_995_v2
    ,low_gmv_995_v2
    ,low_pc2_gmv_995_v2
FROM
    dws_search_main_metrics_${grass_region_without_quote} a
LEFT JOIN
    dws_995_metrics_${grass_region_without_quote} b
ON
    a.card_type = b.card_type
    AND a.search_entrance = b.search_entrance
    AND a.is_ads = b.is_ads
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_search_volume_${grass_region_without_quote} c
ON
    a.search_entrance = c.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_retention_${grass_region_without_quote} d
ON
    a.search_entrance = d.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_ads_performance_${grass_region_without_quote} e
ON
    a.card_type = 'item+video+live'
    AND a.search_entrance = e.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.location = e.location
    AND a.with_item = e.with_item
LEFT JOIN
    dws_video_duration_${grass_region_without_quote} f
ON
    a.search_entrance = f.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = f.card_type
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_srp_duration_${grass_region_without_quote} g
ON
    a.search_entrance = g.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_pdp_duration_${grass_region_without_quote} h
ON
    a.search_entrance = h.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_live_duration_${grass_region_without_quote} i
ON
    a.search_entrance = i.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = i.card_type
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_search_scene_${grass_region_without_quote} j
ON
    a.search_entrance = j.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_norecall_rate_${grass_region_without_quote} k
ON
    a.search_entrance = k.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_video_metrics_${grass_region_without_quote} l
ON
    a.search_entrance = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.card_type = l.card_type
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_live_order_${grass_region_without_quote} m
ON
    a.search_entrance = m.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = m.card_type
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_first_location_${grass_region_without_quote} n
ON
    a.search_entrance = n.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_max_imp_location_${grass_region_without_quote} o
ON
    a.search_entrance = o.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__'
LEFT JOIN
    dws_search_session_count_${grass_region_without_quote} p 
ON
    a.search_entrance = p.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = 'item+video+live'
    AND a.location = p.location
    AND a.with_item = '__ALL__'
LEFT JOIN
    gmv995_v2_metrics_${grass_region_without_quote} q
ON
    a.card_type = q.card_type
    AND a.search_entrance = q.search_entrance
    AND a.is_ads = q.is_ads
    AND a.location = '__ALL__'
    AND a.with_item = '__ALL__';
